CREATE OR REPLACE PROCEDURE sp(arg1 integer, arg2 text, arg3 integer, arg4 integer, arg5 text, arg6 integer)
LANGUAGE plpgsql AS $$
DECLARE
    v_weight_increment integer := 1;
BEGIN
    -- Phase 1
    UPDATE "Player" SET "birthday" = 'phase_1';
    DELETE FROM "Player" WHERE "player_api_id" < arg3;
    UPDATE "Team" SET "team_short_name" = 'log_phase_1';
    DELETE FROM "Team" WHERE "team_fifa_api_id" < arg6;

    -- Phase 2
    UPDATE "Player" SET "birthday" = 'phase_2';
    DELETE FROM "Player" WHERE "player_api_id" < arg3 + 1;
    UPDATE "Team" SET "team_short_name" = 'log_phase_2';
    DELETE FROM "Team" WHERE "team_fifa_api_id" < arg6 + 1;

    -- Phase 3
    UPDATE "Player" SET "birthday" = 'phase_3';
    DELETE FROM "Player" WHERE "player_api_id" < arg3 + 2;
    UPDATE "Team" SET "team_short_name" = 'log_phase_3';
    DELETE FROM "Team" WHERE "team_fifa_api_id" < arg6 + 2;

    -- Phase 4
    UPDATE "Player" SET "birthday" = 'phase_4';
    DELETE FROM "Player" WHERE "player_api_id" < arg3 + 3;
    UPDATE "Team" SET "team_short_name" = 'log_phase_4';
    DELETE FROM "Team" WHERE "team_fifa_api_id" < arg6 + 3;

    -- Phase 5
    UPDATE "Player" SET "birthday" = 'phase_5';
    DELETE FROM "Player" WHERE "player_api_id" < arg3 + 4;
    UPDATE "Team" SET "team_short_name" = 'log_phase_5';
    DELETE FROM "Team" WHERE "team_fifa_api_id" < arg6 + 4;

    -- Phase 6
    UPDATE "Player" SET "birthday" = 'phase_6';
    DELETE FROM "Player" WHERE "player_api_id" < arg3 + 5;
    UPDATE "Team" SET "team_short_name" = 'log_phase_6';
    DELETE FROM "Team" WHERE "team_fifa_api_id" < arg6 + 5;

    -- Phase 7
    UPDATE "Player" SET "birthday" = 'phase_7';
    DELETE FROM "Player" WHERE "player_api_id" < arg3 + 6;
    UPDATE "Team" SET "team_short_name" = 'log_phase_7';
    DELETE FROM "Team" WHERE "team_fifa_api_id" < arg6 + 6;

    -- Phase 8
    UPDATE "Player" SET "birthday" = 'phase_8';
    DELETE FROM "Player" WHERE "player_api_id" < arg3 + 7;
    UPDATE "Team" SET "team_short_name" = 'log_phase_8';
    DELETE FROM "Team" WHERE "team_fifa_api_id" < arg6 + 7;

    -- Phase 9
    UPDATE "Player" SET "birthday" = 'phase_9';
    DELETE FROM "Player" WHERE "player_api_id" < arg3 + 8;
    UPDATE "Team" SET "team_short_name" = 'log_phase_9';
    DELETE FROM "Team" WHERE "team_fifa_api_id" < arg6 + 8;

    -- Post-phase: player weight increase
    UPDATE "Player"
    SET "weight" = "weight" + v_weight_increment
    WHERE "height" < arg1;

    -- Post-phase: team long-name correction
    IF arg5 IS NOT NULL THEN
        UPDATE "Team"
        SET "team_long_name" = arg5
        WHERE "team_short_name" = 'log_phase_9'
          AND "team_api_id" >= arg4;
    END IF;

    -- Post-phase: player-skill correction
    UPDATE "Player_Attributes"
    SET "potential" = "overall_rating"
    WHERE "player_api_id" >= arg3 + 8
      AND "potential" < "overall_rating";

    -- Post-phase: team-tactic correction
    UPDATE "Team_Attributes"
    SET "defenceAggression" = "defencePressure"
    WHERE "defenceAggression" < "defencePressure"
      AND EXISTS (
          SELECT 1
          FROM "Team" t
          WHERE t."team_api_id" = "Team_Attributes"."team_api_id"
            AND t."team_fifa_api_id" >= arg6 + 8
      );
END;
$$;

